// src/react/internal/cx.ts
function cx(...values) {
  const out = [];
  for (const value of values) {
    if (!value && value !== 0) continue;
    if (Array.isArray(value)) {
      const nested = cx(...value);
      if (nested) out.push(nested);
      continue;
    }
    out.push(String(value));
  }
  return out.join(" ");
}

